arguments.schema:
CREATE TABLE users (
  id serial PRIMARY KEY,
  email text NOT NULL UNIQUE,
  created_at timestamptz DEFAULT now()
);
CREATE TABLE orders (
  id serial PRIMARY KEY,
  user_id int NOT NULL REFERENCES users(id),
  total numeric(10,2) NOT NULL,
  status text NOT NULL CHECK (status IN ('open', 'paid'))
);
